import React from 'react';
import { Home, Users, CreditCard, Car, LogOut } from 'lucide-react';

interface User {
  id: string;
  name: string;
  role: string;
  email: string;
}

interface SidebarProps {
  user: User | null;
  onLogout: () => void;
}

const icons = {
  dashboard: Home,
  kyc: Users,
  payments: CreditCard,
  trips: Car,
};

const navItems = [
  { icon: 'dashboard', label: 'Dashboard', section: 'dashboard' },
  { icon: 'kyc', label: 'KYC Management', section: 'kyc' },
  { icon: 'payments', label: 'Payments', section: 'payments' },
  { icon: 'trips', label: 'Trip Reports', section: 'trips' },
];

const Sidebar: React.FC<SidebarProps> = ({ user, onLogout }) => {
  const currentPath = window.location.pathname;

  const getInitials = (name: string | undefined) => {
    if (!name) return 'A';
    return name.split(' ').map(n => n[0]).join('').toUpperCase().slice(0, 2);
  };

  const handleNavClick = (section: string) => {
    window.location.href = `/${section}`;
  };

  return (
    <aside className="sidebar" role="navigation" aria-label="Admin navigation">
      {/* Brand */}
      <div className="sidebar-header">
        <div className="sidebar-brand">
          <div className="sidebar-logo" aria-hidden="true"><Car size={18} /></div>
          <div className="sidebar-brand-text">
            <div className="sidebar-brand-title">Mr. Rideo</div>
            <div className="sidebar-brand-sub">Admin Panel</div>
          </div>
        </div>
      </div>

      {/* Nav */}
      <nav className="sidebar-nav">
        <span className="nav-section-label">Main</span>
        {navItems.map(item => (
          <button
            key={item.section}
            id={`nav-${item.section}`}
            className={`nav-item ${currentPath.includes(item.section) ? 'active' : ''}`}
            onClick={() => handleNavClick(item.section)}
            aria-current={currentPath.includes(item.section) ? 'page' : undefined}
          >
            <span className="nav-icon" aria-hidden="true">
              {React.createElement(icons[item.icon as keyof typeof icons], { size: 18 })}
            </span>
            <span className="nav-label">{item.label}</span>
          </button>
        ))}
      </nav>

      {/* Footer */}
      <div className="sidebar-footer">
        {user && (
          <div className="sidebar-user">
            <div className="user-avatar" aria-hidden="true">
              {getInitials(user.name)}
            </div>
            <div className="user-info">
              <div className="user-name">{user.name || 'Admin'}</div>
              <div className="user-role">{user.role || 'Administrator'}</div>
            </div>
          </div>
        )}
        <button
          id="nav-logout"
          className="nav-item logout"
          onClick={onLogout}
        >
          <span className="nav-icon" aria-hidden="true"><LogOut size={18} /></span>
          <span className="nav-label">Sign out</span>
        </button>
      </div>
    </aside>
  );
};

export default Sidebar;
